package dev.redstoneengineering.physics;
import dev.redstoneengineering.block.*;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import java.util.*;
/** End-game high-conductance thermal/phonon signalling with deliberately finite bandwidth. */
public final class ThermalPulseKernel{private ThermalPulseKernel(){}private record N(BlockPos p,int a){}public static void send(ServerLevel l,BlockPos src,int heat){ArrayDeque<N>q=new ArrayDeque<>();Set<BlockPos>seen=new HashSet<>();for(Direction d:Direction.values())q.add(new N(src.relative(d),heat));while(!q.isEmpty()&&seen.size()<NetworkKernel.MAX_NODES){N n=q.removeFirst();if(n.a<=0||!seen.add(n.p)||!l.hasChunkAt(n.p))continue;var b=l.getBlockState(n.p).getBlock();if(b instanceof ThermalPulseReceiverBlock){InformationRuntime.write(l,"thermal_pulse",n.p,n.a,0,true,100);l.scheduleTick(n.p,b,1);continue;}if(!(b instanceof PhononConduitBlock))continue;int next=n.a-1;for(Direction d:Direction.values())q.add(new N(n.p.relative(d),next));}NetworkKernel.recordScan(l,"phonon",seen.size(),seen.size()>=NetworkKernel.MAX_NODES);}}
